  const addLiveEvent = () => { if (!eventArtist.trim() || !eventStart) return; const event: LiveEvent = { id: makeId(), artist: eventArtist.trim(), venue: eventVenue.trim() || 'Noch offen', start: eventStart, note: eventNote.trim(), addedBy: displayName }; update('liveEvents', [...trip.liveEvents, event]); setEventArtist(''); setEventStart(''); setEventNote('') }
  const sortedLiveEvents = [...trip.liveEvents].sort((a, b) => new Date(a.start).getTime() - new Date(b.start).getTime())
  const openProfileEditor = () => { if (!profileId) { setLoginOpen(true); return } setDraftName(trip.myProfile.name); setDraftPrefix(trip.myProfile.prefix); setDraftVisible(trip.myProfile.visible ?? true); setDraftFlies(trip.myProfile.flies ?? false); setProfileEditOpen(true) }
  const saveProfile = async (event: FormEvent) => { event.preventDefault(); if (!draftName.trim()) return; try { await api('/profile', { method: 'PATCH', body: JSON.stringify({ name: draftName.trim(), prefix: draftPrefix, color: trip.myProfile.color, visible: draftVisible, flies: draftFlies }) }); const oldName = displayName, nextProfile = { ...trip.myProfile, name: draftName.trim(), prefix: draftPrefix, visible: draftVisible, flies: draftFlies }, nextName = `${draftPrefix}${draftName.trim()}`; const fresh = await api('/state'); setTrip(current => ({ ...current, myProfile: nextProfile, participants: fresh.participants, availabilities: current.availabilities.map(entry => entry.name === oldName ? { ...entry, name: nextName } : entry), locationOptions: current.locationOptions.map(option => ({ ...option, suggestedBy: option.suggestedBy === oldName ? nextName : option.suggestedBy, votes: option.votes.map(name => name === oldName ? nextName : name) })), liveEvents: current.liveEvents.map(item => item.addedBy === oldName ? { ...item, addedBy: nextName } : item) })); setProfileEditOpen(false); setError('') } catch (reason) { setError(reason instanceof Error ? reason.message : 'Profil konnte nicht gespeichert werden.') } }
  const uploadAvatar = async (file?: File) => { if (!file) return; try { await api('/profile/avatar', { method: 'PUT', body: file, headers: { 'Content-Type': file.type } }); const fresh = await api('/state'); setTrip(current => ({ ...current, participants: fresh.participants })); setError('') } catch (reason) { setError(reason instanceof Error ? reason.message : 'Profilbild konnte nicht gespeichert werden.') } }
  const sendChat = async (event: FormEvent) => { event.preventDefault(); if (!chatText.trim()) return; try { await api('/chat', { method: 'POST', body: JSON.stringify({ message: chatText }) }); setChatText(''); await loadExtras() } catch (reason) { setError(reason instanceof Error ? reason.message : 'Nachricht konnte nicht gesendet werden.') } }
  const addHighlight = async (event: FormEvent) => { event.preventDefault(); if (!highlightTitle.trim() || !highlightFile) return; try { await api(`/highlights?title=${encodeURIComponent(highlightTitle.trim())}`, { method: 'POST', body: highlightFile, headers: { 'Content-Type': highlightFile.type } }); setHighlightTitle(''); setHighlightFile(null); await loadExtras() } catch (reason) { setError(reason instanceof Error ? reason.message : 'Highlight konnte nicht gespeichert werden.') } }
  const addPastTrip = async (event: FormEvent) => { event.preventDefault(); try { await api('/past-trips', { method: 'POST', body: JSON.stringify({ title: pastTitle, destination: pastDestination, startDate: pastStart, endDate: pastEnd, note: pastNote }) }); setPastTitle(''); setPastDestination(''); setPastStart(''); setPastEnd(''); setPastNote(''); await loadExtras() } catch (reason) { setError(reason instanceof Error ? reason.message : 'Reise konnte nicht archiviert werden.') } }
  const installApp = async () => { if (installPrompt) { await installPrompt.prompt(); const choice = await installPrompt.userChoice; if (choice.outcome === 'accepted') setInstallPrompt(null) } else setInstallHelpOpen(true) }
