    <section className="social-content">{admin && <form className="archive-form" onSubmit={addPastTrip}><h2>Vergangene Reise hinzufügen</h2><div className="archive-fields"><label>Titel<input placeholder="z. B. Malle 2025" value={pastTitle} onChange={e => setPastTitle(e.target.value)} /></label><label>Ziel<input placeholder="Palma de Mallorca" value={pastDestination} onChange={e => setPastDestination(e.target.value)} /></label><label>Start<input type="date" value={pastStart} onChange={e => setPastStart(e.target.value)} /></label><label>Ende<input type="date" value={pastEnd} onChange={e => setPastEnd(e.target.value)} /></label><label className="wide">Erinnerung / Notiz<textarea rows={3} value={pastNote} onChange={e => setPastNote(e.target.value)} /></label></div><button className="save-button" disabled={!pastTitle || !pastDestination || !pastStart || !pastEnd}>Ins Archiv</button></form>}<div className="archive-list">{pastTrips.map(item => <article key={item.id}><span>🌴</span><div><p className="eyebrow">{formatDate(item.start_date, { year: 'numeric' })}</p><h2>{item.title}</h2><strong>📍 {item.destination}</strong><p>{formatDate(item.start_date, { day: 'numeric', month: 'short' })} – {formatDate(item.end_date, { day: 'numeric', month: 'short', year: 'numeric' })}</p>{item.note && <blockquote>{item.note}</blockquote>}</div></article>)}</div>{extrasAuthenticated && !pastTrips.length && <p className="empty-state">Das Reise-Archiv wartet auf seine erste Legende.</p>}{!extrasAuthenticated && <p className="login-notice">🔐 Das Crew-Archiv wird nach dem Beitritt sichtbar.</p>}<button className="back-cta" onClick={() => setSelectedDetail(null)}>← Zur Startseite</button></section>
