      <div className="profile-gallery">{galleryProfiles.map(person => <button className="profile-gallery-card" key={person.id} onClick={() => setSelectedPerson(person)}><span className="gallery-avatar" style={{ background: person.color }}>{person.avatarUrl ? <img src={`${API_BASE}${person.avatarUrl}`} alt="" /> : initials(person.name)}</span><span className="gallery-person"><strong>{person.name}</strong><small>{person.nickname || person.role}</small><em>{person.flies ? '✈️ Fliegt mit' : '🏖️ App-Gast'}</em></span><span className="gallery-badges">{person.achievements?.slice(0, 3).map(badge => <b key={badge.id} title={badge.title}>{badge.icon}</b>)}<i>Öffnen →</i></span></button>)}</div>
      {!galleryProfiles.length && <p className="empty-state">Noch keine weiteren Mittäter entdeckt. Verdächtig …</p>}
